body:
`edit()` and `unedit()` doesn't emit `editing_toggled()` by default, but in c++ we always emit the signal after calling the two methods, `edit()` calls `grab_focus()` and that's why it emits the signal after using it, but `unedit()` doesn't and the signal is only emitted when focus is released and the `LineEdit` is in editing mode.

```c++
		case NOTIFICATION_FOCUS_ENTER: {
			// Only allow editing if the LineEdit is not focused with arrow keys.
			if (!(Input::get_singleton()->is_action_pressed("ui_up") || Input::get_singleton()->is_action_pressed("ui_down") || Input::get_singleton()->is_action_pressed("ui_left") || Input::get_singleton()->is_action_pressed("ui_right"))) {
				edit();
				emit_signal(SNAME("editing_toggled"), true);
			}
		} break;

		case NOTIFICATION_FOCUS_EXIT: {
			if (editing) {
				unedit();
				emit_signal(SNAME("editing_toggled"), false);
			}
		} break;
```

This patch fixes the issue.

```patch
diff --git a/scene/gui/line_edit.cpp b/scene/gui/line_edit.cpp
index 492834f..3e78cbe 100644
--- a/scene/gui/line_edit.cpp
+++ b/scene/gui/line_edit.cpp
@@ -74,6 +74,8 @@ void LineEdit::edit() {

 	show_virtual_keyboard();
 	queue_redraw();
+
+	emit_signal(SNAME("editing_toggled"), true);
 }

 void LineEdit::unedit() {
@@ -94,6 +96,8 @@ void LineEdit::unedit() {
 	if (deselect_on_focus_loss_enabled && !selection.drag_attempt) {
 		deselect();
 	}
+
+	emit_signal(SNAME("editing_toggled"), false);
 }

 bool LineEdit::is_editing() const {
@@ -409,7 +413,6 @@ void LineEdit::gui_input(const Ref<InputEvent> &p_event) {

 			if (editable && !editing) {
 				edit();
-				emit_signal(SNAME("editing_toggled"), true);
 			}

 			accept_event();
@@ -426,7 +429,6 @@ void LineEdit::gui_input(const Ref<InputEvent> &p_event) {

 			if (!editing) {
 				edit();
-				emit_signal(SNAME("editing_toggled"), true);
 			}

 			if (!paste_buffer.is_empty()) {
@@ -527,7 +529,6 @@ void LineEdit::gui_input(const Ref<InputEvent> &p_event) {

 			if (editable && !editing) {
 				edit();
-				emit_signal(SNAME("editing_toggled"), true);
 				return;
 			}
 			queue_redraw();
@@ -623,7 +624,6 @@ void LineEdit::gui_input(const Ref<InputEvent> &p_event) {

 	if (editable && !editing && k->is_action_pressed("ui_text_submit", false)) {
 		edit();
-		emit_signal(SNAME("editing_toggled"), true);
 		accept_event();
 		return;
 	}
@@ -784,7 +784,6 @@ void LineEdit::gui_input(const Ref<InputEvent> &p_event) {

 		if (editing && !keep_editing_on_text_submit) {
 			unedit();
-			emit_signal(SNAME("editing_toggled"), false);
 		}

 		accept_event();
@@ -794,7 +793,6 @@ void LineEdit::gui_input(const Ref<InputEvent> &p_event) {
 	if (k->is_action("ui_cancel")) {
 		if (editing) {
 			unedit();
-			emit_signal(SNAME("editing_toggled"), false);
 		}

 		accept_event();
@@ -1367,14 +1365,12 @@ void LineEdit::_notification(int p_what) {
 			// Only allow editing if the LineEdit is not focused with arrow keys.
 			if (!(Input::get_singleton()->is_action_pressed("ui_up") || Input::get_singleton()->is_action_pressed("ui_down") || Input::get_singleton()->is_action_pressed("ui_left") || Input::get_singleton()->is_action_pressed("ui_right"))) {
 				edit();
-				emit_signal(SNAME("editing_toggled"), true);
 			}
 		} break;

 		case NOTIFICATION_FOCUS_EXIT: {
 			if (editing) {
 				unedit();
-				emit_signal(SNAME("editing_toggled"), false);
 			}
 		} break;

@@ -2168,7 +2164,6 @@ void LineEdit::set_editable(bool p_editable) {

 	if (!editable && editing) {
 		unedit();
-		emit_signal(SNAME("editing_toggled"), false);
 	}
 	_validate_caret_can_draw();

```

Test with this code.

```gdscript
extends LineEdit

"""
prints:
true
false
true
false
true
false
"""

func _ready() -> void:
	editing_toggled.connect(print)
	edit()
	unedit()
	release_focus() # Doesn't emit `editing_toggled`.
	edit()
	release_focus()
	grab_focus()
	unedit()

```

If you change the MRP to
```GDScript
func _process(delta: float) -> void:
	if Input.is_action_just_pressed("h_pressed"):
		if is_editing():
			unedit()
		else:
			edit()
```
`editng_toggled` is not emitted when calling `edit()`. So `edit()` and `unedit()` are consistent, and also consistent with the typical convention that user actions (specifically method calls) don't emit signals. I don't think that's a bug. Pressing Enter to toggle editing will emit the signal correctly.
